// Latin Modern (GUST Font License) embedded as data URIs — the typeface of TeX and of The Art of Computer Programming
window.FONTS_READY = Promise.all([
  new FontFace("LMRoman", "url(data:font/otf;base64,)", { style: "normal" }),
  new FontFace("LMRoman", "url(data:font/otf;base64,)", { style: "italic" }),
  new FontFace("LMMono", "url(data:font/otf;base64,)", { style: "normal" }),
].map((ff) => ff.load().then((x) => { document.fonts.add(x); return x; }).catch(() => null)));
